<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
:root{
  --bg:#0b0f14; --panel:#121a23; --line:#26313c;
  --text:#e8f0f2; --dim:#8b98a5;
  --green:#3fb950; --green-hi:#7ee787; --blue:#58d6ff; --purple:#c678dd;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  min-height:100vh;
  background:
    radial-gradient(1000px 600px at 20% -10%, rgba(88,214,255,.08), transparent 60%),
    radial-gradient(900px 700px at 90% 110%, rgba(198,120,221,.08), transparent 60%),
    var(--bg);
  color:var(--text);
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  display:flex; flex-direction:column; align-items:center; justify-content:center;
  gap:14px; padding:24px 16px;
}
h1{
  margin:0; font-size:clamp(20px,4vw,32px); letter-spacing:1px; text-align:center;
  background:linear-gradient(90deg,var(--green),var(--blue),var(--purple));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.tag{margin:0; color:var(--dim); font-size:13px; text-align:center}
#stage{
  padding:10px; background:var(--panel);
  border:1px solid var(--line); border-radius:16px;
  box-shadow:0 0 0 1px rgba(63,185,80,.06), 0 20px 60px rgba(0,0,0,.55);
}
#life{
  display:block;
  width:clamp(400px, 80vmin, 560px);
  height:clamp(400px, 80vmin, 560px);
  background:#060a0f; border-radius:10px;
  cursor:crosshair; touch-action:none;
}
.controls{display:flex; gap:10px; flex-wrap:wrap; justify-content:center; align-items:center}
button{
  font:inherit; font-size:15px; padding:10px 18px;
  color:var(--text);
  background:linear-gradient(180deg,#1b2530,#141c25);
  border:1px solid var(--line); border-radius:10px; cursor:pointer;
  transition:transform .12s ease, box-shadow .12s ease, border-color .12s ease;
  user-select:none;
}
button:hover{transform:translateY(-2px) rotate(-1deg) scale(1.05); border-color:var(--green); box-shadow:0 6px 18px rgba(63,185,80,.25)}
button:active{transform:translateY(0) scale(.96)}
#play.active{
  background:linear-gradient(180deg,#1f7a3d,#155a2d);
  border-color:var(--green);
  box-shadow:0 0 18px rgba(63,185,80,.45);
}
#speedwrap{display:flex; align-items:center; gap:8px; color:var(--dim); font-size:13px}
#speed{accent-color:var(--green); cursor:pointer}
#stats{display:flex; gap:20px; font-size:13px; color:var(--dim)}
#stats b{color:var(--green-hi); font-weight:600}
.hint{font-size:12px; color:var(--dim); text-align:center; max-width:560px; line-height:1.6}
kbd{
  background:#1b2530; border:1px solid var(--line); border-bottom-width:2px;
  border-radius:5px; padding:1px 6px; font-size:11px;
}
</style>
</head>
<body>
  <h1>🦠 Conway&rsquo;s Game of Life</h1>
  <p class="tag">B3/S23 &middot; 70&times;70 &middot; edges are the void 💀</p>

  <div id="stage">
    <canvas id="life" width="560" height="560"></canvas>
  </div>

  <div class="controls">
    <button id="play" title="run the simulation">▶ Play</button>
    <button id="step" title="advance one generation">⏭ Step</button>
    <button id="random" title="seed a random soup">🎲 Random</button>
    <button id="clear" title="kill everything">🧹 Clear</button>
    <label id="speedwrap">🐢 <input id="speed" type="range" min="2" max="30" value="12"> 🐇</label>
  </div>

  <div id="stats">
    <span>generation <b id="gen">0</b></span>
    <span>alive <b id="alive">0</b></span>
  </div>

  <p class="hint">
    🖱️ click &amp; drag on the grid to paint life &middot;
    <kbd>space</kbd> play/pause &middot; <kbd>S</kbd> step &middot; <kbd>R</kbd> random &middot; <kbd>C</kbd> clear<br>
    try a <b>blinker</b> (3 in a row), a <b>block</b> (2&times;2) or a <b>glider</b> — or just smash 🎲 then ▶
  </p>

<script>
(function () {
  'use strict';

  /* ---------------- model ---------------- */
  var COLS = 70, ROWS = 70, CELL = 8;   // 70x70 cells, 560x560 px backing store

  var canvas = document.getElementById('life');
  canvas.width  = COLS * CELL;
  canvas.height = ROWS * CELL;
  var ctx = canvas.getContext('2d');

  var grid = new Uint8Array(COLS * ROWS);   // current generation
  var next = new Uint8Array(COLS * ROWS);   // scratch buffer => simultaneous updates
  var generation = 0;

  var genEl   = document.getElementById('gen');
  var aliveEl = document.getElementById('alive');
  var playBtn = document.getElementById('play');
  var speedEl = document.getElementById('speed');

  function get(x, y) {
    x = x | 0; y = y | 0;
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return 0;   // edges are dead, no wrap
    return grid[y * COLS + x];
  }

  function set(x, y, v) {
    x = x | 0; y = y | 0;
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return;
    grid[y * COLS + x] = v ? 1 : 0;
    draw();
  }

  /* B3/S23 — every cell's next state is derived from the CURRENT grid into a
     separate buffer, then the buffers are swapped all at once. */
  function step() {
    for (var y = 0; y < ROWS; y++) {
      var row = y * COLS;
      for (var x = 0; x < COLS; x++) {
        var n = 0;
        for (var dy = -1; dy <= 1; dy++) {
          var ny = y + dy;
          if (ny < 0 || ny >= ROWS) continue;
          var nrow = ny * COLS;
          for (var dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            var nx = x + dx;
            if (nx < 0 || nx >= COLS) continue;
            n += grid[nrow + nx];
          }
        }
        var alive = grid[row + x] === 1;
        next[row + x] = (alive ? (n === 2 || n === 3) : (n === 3)) ? 1 : 0;
      }
    }
    var tmp = grid; grid = next; next = tmp;
    generation++;
    draw();
  }

  function clear() {
    grid.fill(0);
    generation = 0;
    draw();
  }

  function randomize() {
    for (var i = 0; i < grid.length; i++) grid[i] = Math.random() < 0.22 ? 1 : 0;
    generation = 0;
    draw();
  }

  /* ---------------- view ---------------- */
  function draw() {
    var W = canvas.width, H = canvas.height, x, y;

    ctx.fillStyle = '#060a0f';
    ctx.fillRect(0, 0, W, H);

    ctx.strokeStyle = 'rgba(88,166,255,0.07)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 1; gx < COLS; gx++) { ctx.moveTo(gx * CELL + .5, 0); ctx.lineTo(gx * CELL + .5, H); }
    for (var gy = 1; gy < ROWS; gy++) { ctx.moveTo(0, gy * CELL + .5); ctx.lineTo(W, gy * CELL + .5); }
    ctx.stroke();

    var count = 0;
    ctx.fillStyle = '#2ea043';
    for (y = 0; y < ROWS; y++)
      for (x = 0; x < COLS; x++)
        if (grid[y * COLS + x]) { count++; ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2); }

    ctx.fillStyle = '#7ee787';
    for (y = 0; y < ROWS; y++)
      for (x = 0; x < COLS; x++)
        if (grid[y * COLS + x]) ctx.fillRect(x * CELL + 3, y * CELL + 3, CELL - 6, CELL - 6);

    genEl.textContent = generation;
    aliveEl.textContent = count;
  }

  /* ---------------- auto-run ---------------- */
  var playing = false, timer = null;

  function setPlaying(p) {
    playing = !!p;
    playBtn.textContent = playing ? '⏸ Pause' : '▶ Play';
    playBtn.classList.toggle('active', playing);
    if (timer) { clearInterval(timer); timer = null; }
    if (playing) timer = setInterval(step, 1000 / (+speedEl.value || 12));
  }

  playBtn.addEventListener('click', function () { setPlaying(!playing); playBtn.blur(); });
  document.getElementById('step').addEventListener('click', function () { setPlaying(false); step(); this.blur(); });
  document.getElementById('random').addEventListener('click', function () { randomize(); this.blur(); });
  document.getElementById('clear').addEventListener('click', function () { setPlaying(false); clear(); this.blur(); });
  speedEl.addEventListener('input', function () { if (playing) setPlaying(true); });

  window.addEventListener('keydown', function (e) {
    var t = (e.target && e.target.tagName) || '';
    if (t === 'INPUT' || t === 'TEXTAREA') return;
    if (e.code === 'Space')          { e.preventDefault(); setPlaying(!playing); }
    else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowRight') { setPlaying(false); step(); }
    else if (e.key === 'r' || e.key === 'R') randomize();
    else if (e.key === 'c' || e.key === 'C') { setPlaying(false); clear(); }
  });

  /* ---------------- paint with mouse / touch ---------------- */
  var painting = false, paintValue = 1, lastCell = -1;

  function eventCell(e) {
    var r = canvas.getBoundingClientRect();
    return {
      x: Math.floor((e.clientX - r.left) / r.width  * COLS),
      y: Math.floor((e.clientY - r.top)  / r.height * ROWS)
    };
  }

  canvas.addEventListener('pointerdown', function (e) {
    e.preventDefault();
    var c = eventCell(e);
    paintValue = get(c.x, c.y) ? 0 : 1;   // first click toggles; the drag paints that value
    painting = true;
    lastCell = c.y * COLS + c.x;
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
    set(c.x, c.y, paintValue);
  });
  canvas.addEventListener('pointermove', function (e) {
    if (!painting) return;
    var c = eventCell(e);
    var i = c.y * COLS + c.x;
    if (i === lastCell) return;
    lastCell = i;
    set(c.x, c.y, paintValue);
  });
  window.addEventListener('pointerup', function () { painting = false; });
  canvas.addEventListener('contextmenu', function (e) { e.preventDefault(); });

  /* ---------------- required grading API ---------------- */
  window.life = {
    w: COLS,
    h: ROWS,
    get: get,
    set: set,
    step: step,
    clear: clear
  };

  draw();   // blank, paused, ready for life
})();
</script>
</body>
</html>
